function problemData(p, title) {
  const d = { title, scenario: { icon: '🧊', body: p.body }, question: p.q, fig: p.fig };
  if (p.opts) { d.options = p.opts.map((t, i) => (i === p.ci ? { text: t, correct: true } : { text: t })); d.note = '풀이: ' + p.hints.join(' · ') + ' → **' + p.opts[p.ci] + '**'; }
  else { d.input = 'count_input'; d.answer = +p.a; d.note = '풀이: ' + p.hints.join(' · ') + ' → **' + p.a + '**'; }
  return d;
}

const LESSONS = {};
const keys = Object.keys(T);
keys.forEach((key, idx) => {
  const t = T[key], n = idx + 1;
  const ex = extras(n, t.ex); const id = (k, i) => ex.filter(e => e.id.startsWith(PFX[k] + '_l' + n + '_'))[i - 1].id;
  const prevItems = idx === 0 ? t.reviewItems : T[keys[idx - 1]].exit;
  const slides = [];
  const add = (block, stage, data, sug, tn) => { const sl = { id: 's' + String(slides.length + 1).padStart(2, '0'), stage, block, data }; if (tn) data.tnote = tn; sl.suggested_extras = sug || []; slides.push(sl); };
  add('cover', '도입', { title: t.cover[0], emoji: t.cover[1] }, [id('video', 1)]);
  add('review', '도입', { title: idx === 0 ? '지난 단원 마지막 시간엔 무엇을 했나요?' : '지난 시간엔 무엇을 했나요?', content: t.review, items: prevItems.map(x => ({ q: x.q, a: x.a })), from: idx === 0 ? t.reviewFrom : keys[idx - 1] }, [id('q', 1)]);
  add('motivate', '도입', { scene_title: t.mot.t, desc: t.mot.desc, question: t.mot.q, img: 'assets/photo/math/' + t.mot.img + '.jpg' }, [id('q', 2), id('real', 1)], t.mot.tn);
  const csug = [[id('e', 1)], [id('tip', 1)], [id('e', 2), id('tip', 2)], [id('q', 3)]];
  t.con.forEach((c, i) => add('concept', '전개', { fig: c.fig, title: c.title, content: c.content }, csug[i], c.tn));
  add('misconception', '전개', { title: '이런 생각을 조심해요', label: '자주 하는 생각', wrong: t.mis[0], right: t.mis[1], hint: t.mis[2] }, [id('x', 1), id('x', 2)], t.mis[3]);
  const bsug = [[id('tip', 3)], [id('e', 3)], [id('q', 4)]];
  t.basic.forEach((p, i) => add('basic_problem', '기본문제', problemData(p, '기본 문제 ' + '①②③'[i]), bsug[i]));
  add('leveled_problem', '기본문제', { title: '수준을 골라 풀어요', levels: t.lev }, [id('q', 5), id('game', 1)], t.levTn);
  add('offline_activity', '응용문제', { title: t.act.t, type: t.act.type, goal: t.act.goal, steps: t.act.steps, solo: t.act.solo, materials: t.act.mats, minutes: t.act.min }, [id('game', 2), id('tip', 4)], t.act.tn);
  add('real_world', '응용문제', { title: t.real[0], scenario: { icon: t.real[1], body: t.real[2] }, content: t.real[3] }, [id('real', 2), id('real', 3)]);
  add('advanced_problem', '응용문제', { title: '생각을 넓혀요', context: t.adv[0], challenge: t.adv[1], note: t.adv[2] }, [id('tip', 5)], t.adv[3]);
  add('exit_ticket', '정리', { title: '오늘 확인해요', items: t.exit, self: ['오늘 배운 것을 혼자 설명할 수 있어요', '조금 헷갈려요', '다시 배우고 싶어요'] }, []);
  add('summary', '정리', { title: '오늘 배운 것', points: t.sum.points, arrows: t.sum.arrows }, [id('real', 1)]);
  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0][0], '🔧 과정·기능 — ' + t.self[0][1], '💛 가치·태도 — ' + t.self[0][2]], prompts: [t.self[1]] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === keys.length - 1 ? '다음 단원엔' : '다음 시간엔', preview: t.next[0], emoji: t.next[1] }, [id('c', 1)]);
  LESSONS[key] = {
    meta: { grade: 6, subject: '수학', term: 2, unit: 2, unit_title: '공간과 입체', n, title: t.title, std: t.std, duration_min: 40, lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '여러 방향에서 보는 공간', source: '2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움' + (key in SELF ? ' · 투영 회수 키 ' + DIR + FILES[SELF[key]] : ' · 자기주도 원문 없는 차시(함께하는 수학)'), src_key: key },
    slides, extras: ex
  };
});

const head = `/* ============================================================================
   6학년 2학기 수학 — 2단원 「공간과 입체」 케이티처 2세대 차시 데이터 (12차시 × 19장)
   - 생성물: kedu/teacher/scripts/gen_g6s2_math_u2.js 가 만든다. 손으로 고치지 말고 생성기(T 표)를 고칠 것.
   - 키: window.LESSONS["u2_l{NN}"] · 주소 stage.html?g=6&s=math&t=2&u=2&l=u2_lNN · slug g6s2_math (6학년 2학기 — 2세대 전용).
   - 재료: 수학 6-2 지도서 2단원 직행(교과서 수·장면 그대로, 그림은 높이 표로) → 케이티처 골격 19장·7요소 + 교사 층(발문·오개념·교실 활동+1인 흐름·extras 22).
   - 계보: u2_l01 복습 = g6s2_math:u1_l11(1단원 문제로 마무리) 출구 퀴즈(글에 선수 학습 2-1 쌓기나무·4-1 뒤집기·5-2 겨냥도) · 이후 차시 복습 = 직전 차시 출구 퀴즈.
   - 그림: skp(쌓기나무 판)·skd(방향 판) — stage2-fig.js 블록 · 그 밖에 tools·u6r.
   - 게이트: 표준/gate_g6s2_math_u2.js
   ============================================================================ */
`;
fs.writeFileSync(OUT, head + '(function () {\n  if (!window.LESSONS) window.LESSONS = {};\n' + keys.map(k => '  window.LESSONS[' + JSON.stringify(k) + '] = ' + JSON.stringify(LESSONS[k]) + ';').join('\n') + '\n})();\n');
console.log('→', path.relative(process.cwd(), OUT), keys.length, '차시 ·', keys.reduce((a, k) => a + LESSONS[k].slides.length, 0), '장 ·', keys.reduce((a, k) => a + LESSONS[k].extras.length, 0), 'extras');
